window.HOEREN_TESTS[87] = {"id":"online-shopping-und-ruecksendung","name":"Online-Shopping und Rücksendung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist der Paketdienst. Ihre Bestellung kommt morgen — aber nicht am Vormittag wie geplant, sondern erst am Nachmittag zwischen 14 und 18 Uhr. Wenn Sie nicht zu Hause sind, geben wir das Paket beim Nachbarn ab. Bitte sorgen Sie dafür, dass jemand da ist. Danke!","gender":"f","q":"Wann kommt das Paket?","opts":["Am Nachmittag.","Am Vormittag.","Am Abend."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Also, ich habe online Schuhe bestellt, aber sie sind zu klein. Jetzt muss ich sie zurückschicken. Das nervt total, ich hätte sie lieber im Laden gekauft. Weißt du, wie das mit der Rücksendung geht? Bekomme ich mein Geld zurück? Ruf an, danke dir!","gender":"m","q":"Warum muss Markus die Schuhe zurückschicken?","opts":["Sie gefallen ihm nicht.","Sie sind kaputt.","Sie sind zu klein."],"correct":2},{"transcript":"Achtung Kunden: Bitte beachten Sie unsere Rückgabe-Regeln. Sie können bestellte Ware innerhalb von 14 Tagen zurückschicken, ohne Grund, nicht nur 7 Tage und nicht erst nach 30 Tagen. Die Ware muss aber unbenutzt sein. Bei uns ist die Rücksendung kostenlos. Legen Sie einfach den Rückschein ins Paket. Das Geld kommt in einer Woche zurück.","gender":"m","q":"Wie lange hat man Zeit für die Rückgabe?","opts":["7 Tage.","30 Tage.","14 Tage."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Ich kaufe fast alles online, es ist so bequem. Aber gestern kam eine Jacke in der falschen Farbe — ich wollte blau, bekam grün. Ärgerlich. Ich schreibe dem Shop eine E-Mail. Du bestellst doch auch viel. Passiert dir das auch manchmal? Melde dich!","gender":"f","q":"Was war das Problem mit der Jacke?","opts":["Falsche Größe.","Falsche Farbe.","Sie war kaputt."],"correct":1},{"transcript":"Liebe Kunden: Ab nächstem Monat ändern sich die Versandkosten. Ab einem Einkauf von 30 Euro ist der Versand weiterhin kostenlos, nicht schon ab 20 Euro und nicht erst ab 50 Euro. Bei kleineren Bestellungen zahlen Sie aber jetzt 5 Euro statt 4. Express-Lieferung am nächsten Tag kostet 10 Euro extra. Danke, dass Sie bei uns einkaufen!","gender":"f","q":"Ab welchem Betrag ist der Versand kostenlos?","opts":["Ab 20 Euro.","Ab 30 Euro.","Ab 50 Euro."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat was bestellt? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Pakete stehen vor der Tür. Weißt du noch wer was bestellt hat?"},{"speaker":"Lisa","gender":"f","text":"Ich habe die Namen auf dem Zettel. Fünf Pakete sind heute angekommen."},{"speaker":"Lukas","gender":"m","text":"Ich habe Kleidung bestellt. Die Hose und das Hemd brauche ich für die Arbeit."},{"speaker":"Lisa","gender":"f","text":"Die Tüte ist blau. Hat jemand Medikamente bestellt?"},{"speaker":"Lukas","gender":"m","text":"Medikamente bestellt bei uns keiner. Die holen wir in der Apotheke."},{"speaker":"Lisa","gender":"f","text":"Ich habe Bücher bestellt, weil ich abends mehr lesen will."},{"speaker":"Lukas","gender":"m","text":"Die liegen auf dem Stuhl. Tom hat etwas mit einem Kabel bestellt."},{"speaker":"Lisa","gender":"f","text":"Tom hat Elektronik bestellt. Er braucht ein neues Gerät für das Telefon."},{"speaker":"Lukas","gender":"m","text":"Dann mach das leise. Hat jemand Werkzeug für den Keller bestellt?"},{"speaker":"Lisa","gender":"f","text":"Werkzeug hat auch keiner bestellt."},{"speaker":"Lukas","gender":"m","text":"Sara hat etwas Großes für das Wohnzimmer bestellt."},{"speaker":"Lisa","gender":"f","text":"Sara hat Möbel bestellt. Ein kleiner Tisch und ein Stuhl für die Ecke."},{"speaker":"Lukas","gender":"m","text":"Die kommen erst morgen mit dem großen Wagen. Tim hat für die Küche bestellt."},{"speaker":"Lisa","gender":"f","text":"Tim hat Lebensmittel bestellt. Reis und Nudeln und zwei Flaschen Saft."},{"speaker":"Lukas","gender":"m","text":"Die Tüte kommt in die Küche."},{"speaker":"Lisa","gender":"f","text":"Ich trage die Pakete jetzt in die Zimmer."}],"options":[{"letter":"a","text":"Lebensmittel"},{"letter":"b","text":"Medikamente"},{"letter":"c","text":"Elektronik"},{"letter":"d","text":"Spielzeug"},{"letter":"e","text":"Möbel"},{"letter":"f","text":"Bücher"},{"letter":"g","text":"Schuhe"},{"letter":"h","text":"Kleidung"},{"letter":"i","text":"Werkzeug"}],"items":[{"person":"Lukas","correct":"h"},{"person":"Lisa","correct":"f"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte ein Paket zurückschicken. Brauche ich Bargeld oder einen Ausweis?"},{"speaker":"Mitarbeiter","gender":"m","text":"Haben Sie den Rückschein? Bargeld und Ausweis brauchen Sie nicht, nur den Schein."},{"speaker":"Kundin","gender":"f","text":"Ja, hier ist der Rückschein. Also kein Bargeld und kein Ausweis?"},{"speaker":"Mitarbeiter","gender":"m","text":"Gut, dann kleben Sie den Rückschein aufs Paket. Nicht Bargeld, nicht den Ausweis, nur den Rückschein."},{"speaker":"Kundin","gender":"f","text":"Verstanden, der Rückschein kommt aufs Paket. Danke."}],"q":"Was braucht die Kundin für die Rücksendung?","opts":["Einen Ausweis.","Bargeld.","Den Rückschein."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Wann bekomme ich mein Geld zurück? Sofort an der Kasse, oder erst nach einem Monat?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Sobald die Ware bei uns ankommt, nicht sofort und nicht erst nach einem Monat."},{"speaker":"Mann","gender":"m","text":"Und das dauert wie lange? Eine Woche, oder wirklich ein Monat?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Etwa eine Woche. Nicht sofort und nicht nach einem Monat, nach etwa einer Woche ist das Geld da."},{"speaker":"Mann","gender":"m","text":"Gut, dann warte ich eine Woche. Danke."}],"q":"Wann kommt das Geld zurück?","opts":["Sofort.","Nach einem Monat.","Nach etwa einer Woche."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Mein Paket ist nicht angekommen. Es ist nicht kaputt und nicht zu teuer, es fehlt einfach."},{"speaker":"Mitarbeiter","gender":"m","text":"Haben Sie eine Sendungsnummer? Wenn es kaputt wäre oder zu teuer, wäre das ein anderer Fall."},{"speaker":"Frau","gender":"f","text":"Ja, hier ist sie. Also das Problem ist: das Paket ist nicht angekommen."},{"speaker":"Mitarbeiter","gender":"m","text":"Ich schaue nach, wo es gerade ist. Nicht kaputt, nicht zu teuer, sondern nicht angekommen."},{"speaker":"Frau","gender":"f","text":"Danke, bitte sagen Sie mir, wo das Paket ist."}],"q":"Was ist das Problem der Frau?","opts":["Das Paket ist nicht angekommen.","Das Paket ist kaputt.","Das Paket ist zu teuer."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Kann ich das Paket beim Nachbarn abholen? Es liegt nicht auf der Post und nicht im Geschäft?"},{"speaker":"Bote","gender":"m","text":"Ja, bei Familie Klein, Nummer 12. Nicht auf der Post und nicht im Geschäft, beim Nachbarn."},{"speaker":"Kunde","gender":"m","text":"Brauche ich etwas? Einen Ausweis für die Post oder fürs Geschäft?"},{"speaker":"Bote","gender":"m","text":"Nur den Zettel im Briefkasten. Das Paket ist beim Nachbarn, nicht auf der Post, nicht im Geschäft."},{"speaker":"Kunde","gender":"m","text":"Alles klar, dann gehe ich zu Familie Klein. Danke."}],"q":"Wo ist das Paket?","opts":["Beim Nachbarn.","Auf der Post.","Im Geschäft."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Die Bluse hat einen Fleck. Muss ich die Rücksendung zahlen, oder zahlt niemand?"},{"speaker":"Mitarbeiter","gender":"m","text":"Das tut mir leid. Schicken Sie sie zurück. Nicht Sie, sondern wir klären das."},{"speaker":"Kundin","gender":"f","text":"Muss ich den Versand zahlen, oder zahlt der Shop?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nein, bei einem Fehler zahlen wir, der Shop. Nicht die Kundin, sondern der Shop."},{"speaker":"Kundin","gender":"f","text":"Gut, dann zahlt der Shop die Rücksendung. Danke."}],"q":"Wer zahlt die Rücksendung?","opts":["Die Kundin.","Der Shop.","Niemand."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Lang, einem Mitarbeiter eines Online-Shops. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Lang, warum kaufen die Leute gern im Internet?"},{"speaker":"Lang","gender":"m","text":"Weil es bequem ist. Man kann zu jeder Zeit bestellen, auch nachts. Online-Shopping ist bequem, weil man immer bestellen kann, nicht nur am Tag."},{"speaker":"Reporterin","gender":"f","text":"Schicken die Leute viel zurück? Ist das ein Problem?"},{"speaker":"Lang","gender":"m","text":"Ja, sehr viel, vor allem Kleidung. Das ist schlecht für die Umwelt. Viele Rücksendungen sind wirklich ein Problem."},{"speaker":"Reporterin","gender":"f","text":"Schadet das Online-Shopping den Geschäften in der Stadt?"},{"speaker":"Lang","gender":"m","text":"Leider ja, viele kleine Läden haben Probleme. Das ist schade. Durch das Internet haben kleine Läden oft weniger Kunden."},{"speaker":"Reporterin","gender":"f","text":"Worauf soll man beim Bestellen achten, zum Beispiel bei der Größe?"},{"speaker":"Lang","gender":"m","text":"Lesen Sie die Beschreibung genau und schauen Sie auf die Größe. Prüfen Sie die Größe vor dem Bestellen, sonst passt die Hose nicht."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie noch? Soll man möglichst viel auf einmal bestellen?"},{"speaker":"Lang","gender":"m","text":"Nein, bestellen Sie nicht zu viel auf einmal. Dann müssen Sie weniger zurückschicken. Möglichst viel auf einmal ist keine gute Idee. Lieber genau bestellen, das spart Zeit und ist besser für die Umwelt. So bleibt weniger Müll übrig."}],"items":[{"q":"Herr Lang findet viele Rücksendungen kein Problem.","correct":"nein"},{"q":"Online-Shopping ist bequem, weil man immer bestellen kann.","correct":"ja"},{"q":"Er sagt, kleine Läden haben durch das Internet Probleme.","correct":"ja"},{"q":"Er rät, die Größe vor dem Bestellen zu prüfen.","correct":"ja"},{"q":"Er meint, man soll möglichst viel auf einmal bestellen.","correct":"nein"}]}]};
